        }
        return Optional.of(new ForeignGuest(fields.passport(), fields.country()));
    }

    @Override
    public DocumentLayout documentLayout() {
        return new BookingReceiptLayout();
    }

    @Override
    public String passport() {
        return passportNumber;
    }

    @Override
    public String country() {
        return countryName;
    }
}
